def get_closest_vowel(word):
    vowels = {'a', 'e', 'i', 'o', 'u', 'A', 'E', 'I', 'O', 'U'}
    closest_vowel = None

    for i in range(len(word) - 2):
        if word[i] in vowels:
            left_char = word[i - 1]
            right_char = word[i + 1]
            if left_char.isalpha() and right_char.isalpha():
                closest_vowel = word[i]
                break

    return closest_vowel if closest_vowel is not None else ""
